code_sketch:
@Entity()
export class User extends BaseEntity {
  @PrimaryGeneratedColumn() id!: number;
  @Column() name!: string;
}

const user = User.create({ name: 'Alice' });
await user.save();                 // INSERT
user.name = 'Bob';
await user.save();                 // UPDATE
await user.remove();

